// Lote 1b, tool 3: the pre-flight checklist, a line-by-line port of src/shared/preflight.ts. Pure C# (no UnityEngine), so the EditMode golden test
// (contracts/golden/preflight.json, generated by the web's own code) runs it directly.
//
// A list of checks with a status (pass / warn / fail / na), its value and where the value comes from, and a summary (ready / warnings / not fit).
// It is informative: nothing here blocks a take-off.
//
// There is no GPS on the wire (the cable carries no fix, satellites or HDOP), so `gps` is "na" ALWAYS: a fix would be a contract change (Lote 2).

using System.Collections.Generic;

namespace WebGL.Telemetry
{
    public enum PreflightStatus { Pass, Warn, Fail, Na }

    /// <summary>Where a value comes from: the five of the honesty rule plus the app itself (the link), the user (the manual boxes) and "none" (no data).</summary>
    public enum PreflightOrigin { Measured, Estimated, Simulated, Synthetic, Command, App, User, None }

    public enum PreflightSource { Replay, Sim, Sitl }

    public enum PreflightVerdict { Ready, Warn, Fail }

    public enum PreflightLink { Open, Connecting, Closed }

    public sealed class PreflightItem
    {
        public string id;
        public PreflightStatus status;
        /// <summary>The number the row shows (rate in Hz, charge in %, volts per cell, the hottest temperature, vibration, fence margin in m, count of faults and alerts).</summary>
        public double? value;
        public string unit;
        /// <summary>A code the UI turns into words (link state, flight state, the hottest component, what raised the faults row).</summary>
        public string detail;
        public PreflightOrigin origin;
    }

    public sealed class PreflightInput
    {
        /// <summary>The `hello` of the session (rateHz, batteryCells and provenance are read), or null before it arrives.</summary>
        public HelloMessage hello;
        /// <summary>The displayed frame (p, bat.v, bat.rem, temp, vib, armed, landed are read), or null.</summary>
        public TelemetryFrame frame;
        public PreflightLink link = PreflightLink.Closed;
        public double rxHz, starvedS;
        /// <summary>Alerts now, and how many of them are critical.</summary>
        public int alerts, criticalAlerts;
        /// <summary>Active faults now.</summary>
        public int faults;
        /// <summary>The geofence of the simulator (only there), else null. Only radius and ceiling are read.</summary>
        public FenceConfig fence;
        /// <summary>The boxes the user ticked, by id (a missing id = not ticked).</summary>
        public IDictionary<string, bool> manual;
        public PreflightSource source;
        /// <summary>An own session (tool 7) replays simulated readings: the origins say so.</summary>
        public bool own;
    }

    public struct PreflightSummary
    {
        public PreflightVerdict verdict;
        public int pass, warn, fail, na;
    }

    public sealed class PreflightResult
    {
        public readonly List<PreflightItem> items = new List<PreflightItem>(12);
        public PreflightSummary summary;

        public PreflightItem Find(string id)
        {
            for (int i = 0; i < items.Count; i++) if (items[i].id == id) return items[i];
            return null;
        }
    }

    public static class Preflight
    {
        /// <summary>Remaining charge: pass from this, warn from `RemWarn`, fail below it.</summary>
        public const double RemPass = 0.6, RemWarn = 0.3;
        /// <summary>Voltage per cell, V: pass from this, warn from `CellWarn`, fail below it.</summary>
        public const double CellPass = 3.7, CellWarn = 3.5;
        /// <summary>The link is "slow" below this fraction of the stream rate, and "late" when no frame came for this long, s.</summary>
        public const double LinkRateRatio = 0.5, StarvedWarnS = 0.5;
        /// <summary>Fence margin (wall or lid) that still passes, m: the one of the geofence tool's amber ring.</summary>
        public const double FenceMarginM = Geofence.NearM;

        /// <summary>The ids of the three boxes the user ticks.</summary>
        public static readonly string[] ManualIds = { "manual.props", "manual.radius", "manual.clear" };

        /// <summary>The ids of every row, in the order the list shows them.</summary>
        public static readonly string[] ItemIds = { "link", "bat.rem", "bat.cell", "temp", "vib", "armed", "fence", "faults", "gps", "manual.props", "manual.radius", "manual.clear" };

        static readonly string[] FrameIds = { "bat.rem", "bat.cell", "temp", "vib", "armed", "fence" };

        static int Level(PreflightStatus s) => s == PreflightStatus.Na ? -1 : s == PreflightStatus.Pass ? 0 : s == PreflightStatus.Warn ? 1 : 2;
        static PreflightStatus OfLevel(int n) => n >= 2 ? PreflightStatus.Fail : n == 1 ? PreflightStatus.Warn : PreflightStatus.Pass;

        /// <summary>pass at or above `pass`, warn at or above `warn`, fail below.</summary>
        static PreflightStatus AtLeast(double x, double pass, double warn) => x >= pass ? PreflightStatus.Pass : x >= warn ? PreflightStatus.Warn : PreflightStatus.Fail;
        /// <summary>pass below `warn`, warn below `crit`, fail from `crit` up.</summary>
        static PreflightStatus Below(double x, double warn, double crit) => x < warn ? PreflightStatus.Pass : x < crit ? PreflightStatus.Warn : PreflightStatus.Fail;

        static PreflightItem Na(string id, PreflightOrigin origin) => new PreflightItem { id = id, status = PreflightStatus.Na, origin = origin };

        /// <summary>Evaluates the checklist.</summary>
        public static PreflightResult Evaluate(PreflightInput input, AlertThresholds th = null)
        {
            th = th ?? AlertThresholds.Default;
            HelloMessage hello = input.hello;
            TelemetryFrame frame = input.frame;
            PreflightSource source = input.source;
            bool sim = source == PreflightSource.Sim || input.own;
            bool replay = source == PreflightSource.Replay && !input.own;
            var r = new PreflightResult();
            List<PreflightItem> items = r.items;

            // link
            {
                double rate = hello != null ? hello.rateHz : 0;
                PreflightStatus status;
                string detail;
                if (input.link == PreflightLink.Closed) { status = PreflightStatus.Fail; detail = "closed"; }
                else if (input.link == PreflightLink.Connecting) { status = PreflightStatus.Warn; detail = "connecting"; }
                else if (input.starvedS > StarvedWarnS) { status = PreflightStatus.Warn; detail = "late"; }
                else if (input.rxHz <= 0) { status = PreflightStatus.Warn; detail = "measuring"; }
                else if (input.rxHz < LinkRateRatio * rate) { status = PreflightStatus.Warn; detail = "slow"; }
                else { status = PreflightStatus.Pass; detail = "open"; }
                items.Add(new PreflightItem { id = "link", status = status, value = input.rxHz, unit = "Hz", detail = detail, origin = PreflightOrigin.App });
            }

            int cells = hello != null && hello.batteryCells > 0 ? hello.batteryCells : 4;

            if (frame != null)
            {
                // bat.rem, bat.cell
                items.Add(new PreflightItem
                {
                    id = "bat.rem", status = AtLeast(frame.bat.rem, RemPass, RemWarn), value = frame.bat.rem * 100, unit = "%",
                    origin = replay ? PreflightOrigin.Estimated : PreflightOrigin.Simulated,
                });
                double cell = frame.bat.v / cells;
                items.Add(new PreflightItem
                {
                    id = "bat.cell", status = AtLeast(cell, CellPass, CellWarn), value = cell, unit = "V",
                    origin = replay ? PreflightOrigin.Measured : PreflightOrigin.Simulated,
                });

                // temp: the motors and the battery, each against its own thresholds; the row shows the one that decides
                {
                    string bestId = "motor1";
                    double bestT = frame.temp[0], bestWarn = th.motorTempWarnC;
                    int bestLevel = -1;
                    for (int i = 0; i < 5; i++)
                    {
                        bool battery = i == 4;
                        double t = frame.temp[i];
                        double warn = battery ? th.batteryTempWarnC : th.motorTempWarnC, crit = battery ? th.batteryTempCritC : th.motorTempCritC;
                        int level = Level(Below(t, warn, crit));
                        if (level > bestLevel || (level == bestLevel && t - warn > bestT - bestWarn))
                        {
                            bestId = battery ? "battery" : "motor" + (i + 1);
                            bestT = t; bestWarn = warn; bestLevel = level;
                        }
                    }
                    Provenance p = hello != null ? hello.provenance : null;
                    bool unavailable = !sim && p != null && p.motorTemp == "unavailable" && p.batteryTemp == "unavailable";
                    PreflightOrigin origin = sim ? PreflightOrigin.Simulated
                        : p != null && p.motorTemp == "measured" && p.batteryTemp == "measured" ? PreflightOrigin.Measured : PreflightOrigin.Estimated;
                    items.Add(unavailable
                        ? Na("temp", PreflightOrigin.None)
                        : new PreflightItem { id = "temp", status = OfLevel(bestLevel), value = bestT, unit = "°C", detail = bestId, origin = origin });
                }

                // vib
                items.Add(new PreflightItem
                {
                    id = "vib", status = Below(frame.vib, th.vibrationWarn, th.vibrationCrit), value = frame.vib, unit = "m/s²",
                    origin = replay ? PreflightOrigin.Measured : PreflightOrigin.Simulated,
                });

                // armed: the checklist is for the ground
                {
                    bool flying = frame.armed && !frame.landed;
                    string detail = flying ? "flying" : frame.armed ? "armedGround" : frame.landed ? "disarmed" : "disarmedAir";
                    items.Add(new PreflightItem
                    {
                        id = "armed", status = flying ? PreflightStatus.Fail : detail == "disarmed" ? PreflightStatus.Pass : PreflightStatus.Warn, detail = detail,
                        origin = replay ? PreflightOrigin.Measured : PreflightOrigin.Simulated,
                    });
                }

                // fence: only the simulator has one the client knows
                if (source == PreflightSource.Sim && !input.own && input.fence != null)
                {
                    Geofence.Margins(input.fence.radius, input.fence.ceiling, frame.p, out _, out _, out double m);
                    items.Add(new PreflightItem
                    {
                        id = "fence", status = m < 0 ? PreflightStatus.Fail : m < FenceMarginM ? PreflightStatus.Warn : PreflightStatus.Pass, value = m, unit = "m",
                        origin = PreflightOrigin.Simulated,
                    });
                }
                else items.Add(Na("fence", PreflightOrigin.None));
            }
            else
            {
                foreach (string id in FrameIds) items.Add(Na(id, PreflightOrigin.None));
            }

            // faults: active faults and alerts
            {
                bool critical = input.criticalAlerts > 0;
                int count = input.faults + input.alerts;
                string detail = input.faults > 0 ? "faults" : critical ? "critical" : input.alerts > 0 ? "warning" : "none";
                PreflightStatus status = input.faults > 0 || critical ? PreflightStatus.Fail : input.alerts > 0 ? PreflightStatus.Warn : PreflightStatus.Pass;
                items.Add(new PreflightItem
                {
                    id = "faults", status = frame != null ? status : PreflightStatus.Na, value = frame != null ? count : (double?)null, detail = frame != null ? detail : null,
                    origin = frame == null ? PreflightOrigin.None : sim ? PreflightOrigin.Simulated : replay ? PreflightOrigin.Synthetic : PreflightOrigin.Command,
                });
            }

            // gps: the wire carries no GPS
            items.Add(Na("gps", PreflightOrigin.None));

            // manual boxes: the replay has nobody at the field to tick them
            foreach (string id in ManualIds)
            {
                if (source == PreflightSource.Replay) { items.Add(Na(id, PreflightOrigin.User)); continue; }
                bool ticked = input.manual != null && input.manual.TryGetValue(id, out bool v) && v;
                items.Add(new PreflightItem { id = id, status = ticked ? PreflightStatus.Pass : PreflightStatus.Warn, origin = PreflightOrigin.User });
            }

            var sum = new PreflightSummary();
            foreach (PreflightItem i in items)
            {
                if (i.status == PreflightStatus.Pass) sum.pass++;
                else if (i.status == PreflightStatus.Warn) sum.warn++;
                else if (i.status == PreflightStatus.Fail) sum.fail++;
                else sum.na++;
            }
            sum.verdict = sum.fail > 0 ? PreflightVerdict.Fail : sum.warn > 0 ? PreflightVerdict.Warn : PreflightVerdict.Ready;
            r.summary = sum;
            return r;
        }

        /// <summary>The ids of the checks that fail: what the "Take off" button warns about (a warning does not count).</summary>
        public static List<string> FailingIds(PreflightResult r)
        {
            var l = new List<string>();
            if (r != null) foreach (PreflightItem i in r.items) if (i.status == PreflightStatus.Fail) l.Add(i.id);
            return l;
        }

        /// <summary>What pressing "Take off" does: true = ask first ("Take off anyway") because a check fails; false = send straight away (warnings only, or no checks).</summary>
        public static bool TakeoffAsks(PreflightResult r) => FailingIds(r).Count > 0;

        // wire names (the golden and the keys of the texts)
        public static string Name(PreflightStatus s) => s == PreflightStatus.Pass ? "pass" : s == PreflightStatus.Warn ? "warn" : s == PreflightStatus.Fail ? "fail" : "na";
        public static string Name(PreflightVerdict v) => v == PreflightVerdict.Ready ? "ready" : v == PreflightVerdict.Warn ? "warn" : "fail";

        public static string Name(PreflightOrigin o)
        {
            switch (o)
            {
                case PreflightOrigin.Measured: return "measured";
                case PreflightOrigin.Estimated: return "estimated";
                case PreflightOrigin.Simulated: return "simulated";
                case PreflightOrigin.Synthetic: return "synthetic";
                case PreflightOrigin.Command: return "command";
                case PreflightOrigin.App: return "app";
                case PreflightOrigin.User: return "user";
                default: return "none";
            }
        }
    }
}
